// EUCLIDEAN GCD — O(log(min(a,b)))
function gcd(a, b) {
    while (b !== 0) {
        [a, b] = [b, a % b]; // a = b, b = a % b
    }
    return a;
}
// Recursive version:
function gcd_r(a, b) {
    return b === 0 ? a : gcd_r(b, a % b);
}

console.log(gcd(48, 18)); // 6  (48=8*6, 18=3*6)
console.log(gcd(100, 75)); // 25
console.log(gcd(17, 5));   // 1 (co-prime)

// LCM — O(log(min(a,b))) via GCD
function lcm(a, b) {
    return (a / gcd(a, b)) * b; // divide BEFORE multiply to avoid overflow
}
console.log(lcm(4, 6));  // 12
console.log(lcm(12, 8)); // 24

// GCD OF ARRAY
function gcdArray(nums) {
    return nums.reduce((g, n) => gcd(g, n));
}
console.log(gcdArray([12, 8, 6]));  // 2
console.log(gcdArray([12, 8, 16])); // 4

// APPLICATIONS:

// 1. Simplify fraction a/b
function simplify(a, b) {
    const g = gcd(Math.abs(a), Math.abs(b));
    return [a / g, b / g];
}
console.log(simplify(6, 9));   // [2, 3]
console.log(simplify(15, 25)); // [3, 5]

// 2. Water Jug Problem: can we measure exactly target litres
//    using jugs of capacity a and b?
//    Possible iff target % gcd(a, b) === 0
function waterJug(a, b, target) {
    return target % gcd(a, b) === 0;
}
console.log(waterJug(3, 5, 4)); // true  (gcd(3,5)=1 divides 4)
console.log(waterJug(2, 6, 5)); // false (gcd(2,6)=2 does not divide 5)

