// FAST POWER / myPow (#50) — O(log n)
function myPow(x, n) {
    if (n < 0) { x = 1 / x; n = -n; } // handle negative exponent
    let result = 1;
    while (n > 0) {
        if (n & 1) result *= x;   // odd: multiply result by current x
        x *= x;                   // square the base
        n >>= 1;                  // right shift: move to next bit
    }
    return result;
}

console.log(myPow(2, 10));   // 1024
console.log(myPow(2, -2));   // 0.25
console.log(myPow(2.1, 3));  // 9.261000000000001

// TRACE for x=2, n=13 (binary 1101):
// n=13(1101): n&1=1 -> result=1*2=2. x=4. n=6(0110)
// n=6(0110):  n&1=0 -> result=2. x=16. n=3(0011)
// n=3(0011):  n&1=1 -> result=2*16=32. x=256. n=1(0001)
// n=1(0001):  n&1=1 -> result=32*256=8192. x=65536. n=0
// Return 8192. Verify: 2^13=8192 ✓

// RECURSIVE VERSION
function myPow_r(x, n) {
    if (n === 0) return 1;
    if (n < 0)  return myPow_r(1/x, -n);
    if (n % 2 === 0) {
        const half = myPow_r(x, n/2);
        return half * half;       // compute once, square (not call twice)
    }
    return x * myPow_r(x, n-1);
}

// MODULAR EXPONENTIATION — (x^n) mod m
function modPow(x, n, m) {
    let result = 1n; // BigInt to avoid overflow
    x = BigInt(x) % BigInt(m);
    n = BigInt(n);
    const mod = BigInt(m);
    while (n > 0n) {
        if (n & 1n) result = (result * x) % mod;
        x = (x * x) % mod;
        n >>= 1n;
    }
    return Number(result);
}
console.log(modPow(2, 10, 1000)); // 24 (1024 mod 1000)
console.log(modPow(2, 100, 1e9 + 7)); // some large mod result

