// ROTATE IMAGE (#48) — 90 degrees clockwise in-place
// O(n^2) time, O(1) space
function rotate(matrix) {
    const n = matrix.length;

    // STEP 1: Transpose — swap matrix[i][j] with matrix[j][i]
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) { // j starts at i+1: upper triangle only
            [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
        }
    }

    // STEP 2: Reverse each row
    for (let i = 0; i < n; i++) {
        matrix[i].reverse();
    }
}

// TEST
const mat = [[1,2,3],[4,5,6],[7,8,9]];
rotate(mat);
console.log(mat); // [[7,4,1],[8,5,2],[9,6,3]]
// Original:   Transposed: Reversed rows:
// 1 2 3       1 4 7       7 4 1
// 4 5 6  -->  2 5 8  -->  8 5 2
// 7 8 9       3 6 9       9 6 3

// ROTATE 90 COUNTER-CLOCKWISE
function rotateCCW(matrix) {
    const n = matrix.length;
    // Step 1: Reverse each row first
    for (let i = 0; i < n; i++) matrix[i].reverse();
    // Step 2: Transpose
    for (let i = 0; i < n; i++)
        for (let j = i+1; j < n; j++)
            [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
}

// ROTATE 180 DEGREES
function rotate180(matrix) {
    const n = matrix.length;
    // Reverse the entire matrix (reverse rows order, then reverse each row)
    matrix.reverse();                      // flip vertically
    for (let i = 0; i < n; i++) matrix[i].reverse(); // flip each row horizontally
}

// LAYER-BY-LAYER ALTERNATIVE for 90 CW:
// Directly cycle four elements: (i,j) -> (j, n-1-i) -> (n-1-i, n-1-j) -> (n-1-j, i)
function rotate_cycle(matrix) {
    const n = matrix.length;
    for (let layer = 0; layer < Math.floor(n/2); layer++) {
        const last = n - 1 - layer;
        for (let i = layer; i < last; i++) {
            const offset = i - layer;
            const temp = matrix[layer][i];
            matrix[layer][i]              = matrix[last-offset][layer];     // left->top
            matrix[last-offset][layer]    = matrix[last][last-offset];      // bottom->left
            matrix[last][last-offset]     = matrix[i][last];                // right->bottom
            matrix[i][last]               = temp;                           // top->right
        }
    }
}

