// BONUS: PLUS ONE (#66) — add one to number represented as digit array
function plusOne(digits) {
    for (let i = digits.length - 1; i >= 0; i--) {
        if (digits[i] < 9) { digits[i]++; return digits; }
        digits[i] = 0; // carry
    }
    return [1, ...digits]; // overflow: prepend 1
}
console.log(plusOne([1,2,3])); // [1,2,4]
console.log(plusOne([9,9,9])); // [1,0,0,0]

// HAPPY NUMBER (#202) — is n a happy number?
// Happy: sum of squares of digits eventually reaches 1
// Use Floyd's cycle detection to detect loops
function isHappy(n) {
    function sumOfSquares(num) {
        let sum = 0;
        while (num > 0) { const d = num % 10; sum += d*d; num = Math.floor(num/10); }
        return sum;
    }
    let slow = n, fast = sumOfSquares(n);
    while (fast !== 1 && slow !== fast) {
        slow = sumOfSquares(slow);
        fast = sumOfSquares(sumOfSquares(fast));
    }
    return fast === 1;
}
console.log(isHappy(19)); // true  (1^2+9^2=82, 8^2+2^2=68, ...)->1
console.log(isHappy(2));  // false (enters cycle)

